function averageOfLevels(root: TreeNode | null): number[] {
  const result: number[] = [];
  if (root === null) {
    return result;
  }

  // Текущий уровень дерева
  let level: TreeNode[] = [root];

  while (level.length > 0) {
    // Узлы следующего уровня соберём по ходу обхода текущего
    const next: TreeNode[] = [];
    let sum = 0;

    for (const node of level) {
      sum += node.val;
      if (node.left !== null) next.push(node.left);
      if (node.right !== null) next.push(node.right);
    }

    // Уровень пройден целиком — записываем его среднее
    result.push(sum / level.length);
    level = next;
  }

  return result;
}

// Время: O(n) — каждый узел обрабатывается один раз
// Память: O(w) — максимальная ширина уровня
